using System;
using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PlayerCurrentOmens", menuName = "Data/Battle/Omens System/Player Current Omens")]
public class PlayerCurrentOmens : ScriptableObject
{
	[Header("Runtime Omens")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private List<RuntimeOmenData> runtimeOmens = new List<RuntimeOmenData>();

	[Header("Discovered System")]
	[SerializeField]
	private OmensListsList omensListsList;

	[Header("Statistics")]
	[SerializeField]
	private OmenTier starBlessingTier;

	[SerializeField]
	private OmenTier blackHoleBlessingTier;

	[Header("Save System")]
	[SerializeField]
	private SaveSystem saveSystem;

	[NonSerialized]
	public List<OmenInstance> ActiveOmens = new List<OmenInstance>();

	private Character currentCharacter => ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter;

	public List<OmenData> DefaultOmens => currentCharacter.CharacterOmens.DefaultOmens;

	public List<RuntimeOmenData> RuntimeOmens => runtimeOmens;

	public void OnResetToStartRunState()
	{
		runtimeOmens.Clear();
		ResetBlessingsToStartRunState();
	}

	private void ResetBlessingsToStartRunState()
	{
		if (!saveSystem.HasModBlessingsSetBattleSaveKey(currentCharacter.CharacterName) || ReferenceSingleton<AssetsReference>.Instance.GameController.IsDailyRun)
		{
			SetOmens(DefaultOmens);
			omensListsList.BlessingsDiscovered(DefaultOmens);
			return;
		}
		SaveSystem.ModBlessingsSetSave modBlessingsSetInfo = saveSystem.LoadModBlessingsSetBattle(currentCharacter.CharacterName);
		CharacterOmens.ModBlessingsSetInfo modBlessingsSetInfo2 = currentCharacter.CharacterOmens.CustomOmenList.Find((CharacterOmens.ModBlessingsSetInfo _) => _.PublishedId == modBlessingsSetInfo.PublishedId);
		if (modBlessingsSetInfo2 == null)
		{
			SetOmens(DefaultOmens);
			omensListsList.BlessingsDiscovered(DefaultOmens);
			return;
		}
		CharacterOmens.BlessingsSetInfo blessingsSetInfo = modBlessingsSetInfo2.BlessingsSetInfosList.Find((CharacterOmens.BlessingsSetInfo _) => _.SetId == modBlessingsSetInfo.SetId);
		if (blessingsSetInfo == null)
		{
			SetOmens(DefaultOmens);
			omensListsList.BlessingsDiscovered(DefaultOmens);
		}
		else
		{
			SetOmens(blessingsSetInfo.Omens);
		}
	}

	private void SetOmens(List<OmenData> omenList)
	{
		List<OmenData> list = omenList.Duplicate();
		for (int i = 0; i < list.Count; i++)
		{
			if (!(list[i] == null))
			{
				runtimeOmens.Add(new RuntimeOmenData(list[i], 0));
			}
		}
	}

	public List<OmenData> GetOmenDataList()
	{
		List<OmenData> list = new List<OmenData>();
		for (int i = 0; i < runtimeOmens.Count; i++)
		{
			list.Add(runtimeOmens[i].OmenData);
		}
		return list;
	}

	public bool PlayerHasBlessing(OmenData omenData)
	{
		for (int i = 0; i < runtimeOmens.Count; i++)
		{
			if (runtimeOmens[i].OmenData == omenData)
			{
				return true;
			}
		}
		return false;
	}

	public bool PlayerHasBlessing(string omenDataName)
	{
		for (int i = 0; i < runtimeOmens.Count; i++)
		{
			if (runtimeOmens[i].OmenData.name == omenDataName)
			{
				return true;
			}
		}
		return false;
	}

	public bool PlayerHasAnyOfThisBlessings(List<OmenData> omenDatas)
	{
		for (int i = 0; i < runtimeOmens.Count; i++)
		{
			for (int j = 0; j < omenDatas.Count; j++)
			{
				if (runtimeOmens[i].OmenData == omenDatas[j])
				{
					return true;
				}
			}
		}
		return false;
	}

	public bool PlayerHasAllOfTheseBlessings(List<OmenData> omenDatas)
	{
		int count = omenDatas.Count;
		int num = 0;
		for (int i = 0; i < runtimeOmens.Count; i++)
		{
			for (int j = 0; j < omenDatas.Count; j++)
			{
				if (runtimeOmens[i].OmenData == omenDatas[j])
				{
					num++;
				}
			}
		}
		if (num == count)
		{
			return true;
		}
		return false;
	}

	public OmenInstance GetOmenInstance(OmenData omenData)
	{
		for (int i = 0; i < ActiveOmens.Count; i++)
		{
			if (ActiveOmens[i].OmenData == omenData)
			{
				return ActiveOmens[i];
			}
		}
		return null;
	}

	public int GetRuntimeOmenIndex(OmenData omenData)
	{
		for (int i = 0; i < runtimeOmens.Count; i++)
		{
			if (runtimeOmens[i].OmenData == omenData)
			{
				return i;
			}
		}
		return -1;
	}

	public int GetStarBlessingsAmount()
	{
		int num = 0;
		for (int i = 0; i < runtimeOmens.Count; i++)
		{
			if (runtimeOmens[i].OmenData.OmenTier == starBlessingTier)
			{
				num++;
			}
		}
		return num;
	}

	public int GetBlackHoleBlessingsAmount()
	{
		int num = 0;
		for (int i = 0; i < runtimeOmens.Count; i++)
		{
			if (runtimeOmens[i].OmenData.OmenTier == blackHoleBlessingTier)
			{
				num++;
			}
		}
		return num;
	}
}
